/* BlueFix Start-Splash – erscheint jedes Mal, wenn die App geöffnet wird.
   Einbinden: <script src="start-splash.js"></script> möglichst weit oben im <head> der index.html. */
(function () {
  // Kommt man über splash.html, wurde der Splash schon gezeigt -> nicht doppelt anzeigen
  try {
    if (sessionStorage.getItem("bfx_skip_start")) { sessionStorage.removeItem("bfx_skip_start"); return; }
  } catch (e) {}
  var LOGO = "data:image/png;base64,";
  var reduce = window.matchMedia && matchMedia("(prefers-reduced-motion: reduce)").matches;
  var MIN_MS = reduce ? 600 : 3400; // Mindestdauer des Splash Screens
  var MAX_MS = 10000;               // spätestens danach wird ausgeblendet

  var css =
    "#bfx-splash{position:fixed;inset:0;z-index:2147483647;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:26px;background:#04070d;overflow:hidden;transition:opacity .7s ease,visibility .7s}" +
    "#bfx-splash.bfx-out{opacity:0;visibility:hidden}" +
    "#bfx-splash::before{content:'';position:absolute;inset:0;opacity:0;background-image:linear-gradient(rgba(30,120,255,.08) 1px,transparent 1px),linear-gradient(90deg,rgba(30,120,255,.08) 1px,transparent 1px);background-size:44px 44px;-webkit-mask-image:radial-gradient(circle at 50% 50%,#000 0,transparent 70%);mask-image:radial-gradient(circle at 50% 50%,#000 0,transparent 70%);animation:bfx-in 1s ease .1s forwards}" +
    "#bfx-splash::after{content:'';position:absolute;inset:0;opacity:0;background:radial-gradient(circle at 50% 50%,rgba(20,110,255,.22),transparent 55%);animation:bfx-in 1.6s ease .3s forwards}" +
    ".bfx-logo{position:relative;z-index:1;width:min(560px,84vw)}" +
    ".bfx-logo img{display:block;width:100%;height:auto;clip-path:inset(0 100% 0 0);animation:bfx-reveal 1.5s cubic-bezier(.65,0,.25,1) .5s forwards}" +
    ".bfx-logo i{position:absolute;top:-6%;bottom:-6%;left:0;width:2px;background:#3d8bff;box-shadow:0 0 18px 4px rgba(61,139,255,.7);opacity:0;animation:bfx-scan 1.5s cubic-bezier(.65,0,.25,1) .5s forwards}" +
    ".bfx-bar{position:relative;z-index:1;width:min(560px,84vw);height:3px;border-radius:2px;background:rgba(61,139,255,.18);overflow:hidden;opacity:0;animation:bfx-in .5s ease 1.2s forwards}" +
    ".bfx-bar b{display:block;height:100%;background:#2f7bff;box-shadow:0 0 10px rgba(47,123,255,.9);transform:scaleX(0);transform-origin:left;animation:bfx-fill 2s cubic-bezier(.4,0,.2,1) 1.3s forwards}" +
    ".bfx-label{position:relative;z-index:1;font:500 13px/1 system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;letter-spacing:.04em;color:#7f93b8;opacity:0;animation:bfx-in .6s ease 1.4s forwards}" +
    "@keyframes bfx-in{to{opacity:1}}" +
    "@keyframes bfx-reveal{to{clip-path:inset(0 0 0 0)}}" +
    "@keyframes bfx-scan{0%{left:0;opacity:1}90%{opacity:1}100%{left:100%;opacity:0}}" +
    "@keyframes bfx-fill{to{transform:scaleX(1)}}" +
    "@media (prefers-reduced-motion:reduce){#bfx-splash *,#bfx-splash::before,#bfx-splash::after{animation-duration:.01s!important;animation-delay:0s!important}}";

  var style = document.createElement("style");
  style.textContent = css;
  document.documentElement.appendChild(style);

  var el = document.createElement("div");
  el.id = "bfx-splash";
  el.setAttribute("role", "status");
  el.setAttribute("aria-label", "BlueFix wird geladen");
  el.innerHTML =
    '<div class="bfx-logo"><img src="' + LOGO + '" alt="BlueFix Handy Reparatur"><i></i></div>' +
    '<div class="bfx-bar"><b></b></div>' +
    '<div class="bfx-label">Wird geladen …</div>';
  document.documentElement.appendChild(el);

  var root = document.documentElement;
  var prevOverflow = root.style.overflow;
  root.style.overflow = "hidden";

  var timeUp = false;
  var loaded = document.readyState === "complete";
  var done = false;

  function hide() {
    if (done) return;
    done = true;
    el.classList.add("bfx-out");
    root.style.overflow = prevOverflow;
    setTimeout(function () {
      el.remove();
      style.remove();
    }, 800);
  }
  function tryHide() {
    if (timeUp && loaded) hide();
  }

  setTimeout(function () { timeUp = true; tryHide(); }, MIN_MS);
  setTimeout(hide, MAX_MS);
  window.addEventListener("load", function () { loaded = true; tryHide(); });
})();
